CREATE TABLE "public"."raw_event" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "created_at" timestamp with time zone NOT NULL DEFAULT now(),
    "calendar_id" bigint NOT NULL,
    "event" jsonb NOT NULL,
    "provider_id" text NOT NULL
);

CREATE UNIQUE INDEX raw_event_calendar_id_provider_id_key ON public.raw_event USING btree (calendar_id, provider_id);

CREATE UNIQUE INDEX raw_event_pkey ON public.raw_event USING btree (id);

ALTER TABLE "public"."raw_event"
    ADD CONSTRAINT "raw_event_pkey" PRIMARY KEY USING INDEX "raw_event_pkey";

ALTER TABLE "public"."raw_event"
    ADD CONSTRAINT "raw_event_calendar_id_fkey" FOREIGN KEY (calendar_id) REFERENCES calendar (id) ON DELETE CASCADE NOT valid;

ALTER TABLE "public"."raw_event" validate CONSTRAINT "raw_event_calendar_id_fkey";

ALTER TABLE "public"."raw_event"
    ADD CONSTRAINT "raw_event_calendar_id_provider_id_key" UNIQUE USING INDEX "raw_event_calendar_id_provider_id_key";

